    pctx.strokeStyle = '#10b981';
    pctx.beginPath(); pctx.arc(256, 256, 240, 0, Math.PI * 2); pctx.stroke();
    pctx.lineWidth = 5;
    pctx.strokeStyle = '#34d399';
    pctx.beginPath(); pctx.arc(256, 256, 210, 0, Math.PI * 2); pctx.stroke();
    pctx.strokeStyle = 'rgba(52, 211, 153, 0.45)';
    pctx.beginPath(); pctx.arc(256, 256, 140, 0, Math.PI * 2); pctx.stroke();

    // Giant glowing Peace Symbol in the center
